import sqlite3

def get_all_user_orders(user_ids):
    conn = sqlite3.connect('app.db')
    results = {}
    for uid in user_ids:
        # N+1 query vulnerability inside loop
        orders = conn.execute(f"SELECT * FROM orders WHERE user_id = ?", (uid,)).fetchall()
        results[uid] = orders
    return results
